window.__votdWeek && window.__votdWeek({"week":"2029-01-22","reading":"Doctrine and Covenants 2; Joseph Smith—History 1:27–65","days":[{"d":"2029-01-22","ref":"D&C 2:1","b":"D&C","c":2,"v":1,"he":"הִנֵּה אֲגַלֶּה לָכֶם אֶת־הַכְּהֻנָּה בְּיַד אֵלִיָּהוּ הַנָּבִיא לִפְנֵי בּוֹא יוֹם יְהוָה הַגָּדוֹל וְהַנּוֹרָא׃","en":"Behold, I will reveal unto you the Priesthood, by the hand of Elijah the prophet, before the coming of the great and dreadful day of the Lord."},{"d":"2029-01-23","ref":"D&C 2:2","b":"D&C","c":2,"v":2,"he":"וְנָטַע בְּלִבּוֹת הַבָּנִים אֶת־הַהַבְטָחוֹת אֲשֶׁר נִתְּנוּ לָאָבוֹת וְלִבּוֹת הַבָּנִים יָשׁוּבוּ עַל־אֲבוֹתָם׃","en":"And he shall plant in the hearts of the children the promises made to the fathers, and the hearts of the children shall turn to their fathers."},{"d":"2029-01-24","ref":"D&C 2:3","b":"D&C","c":2,"v":3,"he":"וְלוּלֵא כֵן הָיְתָה כׇל־הָאָרֶץ לְחֵרֶם בְּבוֹאוֹ׃","en":"If it were not so, the whole earth would be utterly wasted at his coming."},{"d":"2029-01-25","ref":"Joseph Smith—History 1:32","b":"JS—History","c":1,"v":32,"he":"לֹא רַק גְּלִימָתוֹ הָיְתָה לְבָנָה בְּיוֹתֵר אֶלָּא כׇּל גּוּפוֹ הָיָה נֶהְדָּר מֵעֵבֶר לְתֵאוּר וּפָנָיו בֶּאֱמֶת כַּבָּרָק הֶחָדֶר הָיָה מֵאִיר מְאוֹד אֲבָל לֹא כֹּה בָּהִיר כְּסָבִיב גּוּפוֹ בְּהַבִּיטִי עָלָיו בָּרִאשׁוֹנָה פָּחַדְתִּי אֲבָל הַפַּחַד עָבַר מְהֵרָה׃","en":"Not only was his robe exceedingly white, but his whole person was glorious beyond description, and his countenance truly like lightning. The room was exceedingly light, but not so very bright as immediately around his person. When I first looked upon him, I was afraid; but the fear soon left me."},{"d":"2029-01-26","ref":"Joseph Smith—History 1:33","b":"JS—History","c":1,"v":33,"he":"קָרָא לִי בִשְׁמִי וְאָמַר לִי שֶׁהוּא שָׁלִיחַ שָׁלוּחַ מִלִּפְנֵי הָאֱלֹהִים אֵלַי וּשְׁמוֹ מוֹרוֹנִי שֶׁלֵּאלֹהִים יֵשׁ מְלָאכָה לִי לַעֲשׂוֹת וּשְׁמִי יִהְיֶה יָדוּעַ לְטוֹב וּלְרַע בֵּין כׇּל הַגּוֹיִם וְהַמִּשְׁפָּחוֹת וְהַלְּשׁוֹנוֹת אוֹ שֶׁיְּדֻבַּר עָלָיו לְטוֹב וּלְרַע בֵּין כׇּל הָעַמִּים׃","en":"He called me by name, and said unto me that he was a messenger sent from the presence of God to me, and that his name was Moroni; that God had a work for me to do; and that my name should be had for good and evil among all nations, kindreds, and tongues, or that it should be both good and evil spoken of among all people."},{"d":"2029-01-27","ref":"Joseph Smith—History 1:37","b":"JS—History","c":1,"v":37,"he":"כִּי הִנֵּה הַיּוֹם בָּא בֹּעֵר כַּתַּנּוּר וְכׇל זֵדִים וְכׇל עֹשֵׂי רִשְׁעָה יִבְעֲרוּ כַּקַּשׁ כִּי הַבָּאִים יְבַעֲרוּם אָמַר יְהוָה צְבָאוֹת וְלֹא יַשְׁאִיר לָהֶם שֹׁרֶשׁ וְעָנָף׃","en":"For behold, the day cometh that shall burn as an oven, and all the proud, yea, and all that do wickedly shall burn as stubble; for they that come shall burn them, saith the Lord of Hosts, that it shall leave them neither root nor branch."},{"d":"2029-01-28","ref":"Joseph Smith—History 1:38","b":"JS—History","c":1,"v":38,"he":"וְעוֹד צִטֵּט אֶת־הַפָּסוּק הַחֲמִישִׁי כָּךְ הִנֵּה אֲגַלֶּה לָכֶם אֶת־הַכְּהֻנָּה בְּיַד אֵלִיָּהוּ הַנָּבִיא לִפְנֵי בֹּא יוֹם יְהוָה הַגָּדוֹל וְהַנּוֹרָא׃","en":"And again, he quoted the fifth verse thus: Behold, I will reveal unto you the Priesthood, by the hand of Elijah the prophet, before the coming of the great and dreadful day of the Lord."}]});
